<?php $safeUrl=is_string($source['url']??null) && filter_var($source['url'],FILTER_VALIDATE_URL) && in_array(strtolower((string)parse_url($source['url'],PHP_URL_SCHEME)),['http','https'],true); ?>
<div class="container py-4">
    <h1 class="h3">Source #<?= (int)$source['id'] ?> — <?= e($source['title']) ?></h1>
    <p>Status: <strong><?= e($source['status']) ?></strong>. Verification means identity/provenance checked, not treatment effectiveness.</p>
    <p>Bibliographic identity is immutable. Corrections create a new source version.</p>
    <dl class="row"><?php foreach (['source_type','author_or_organization','publication','citation_text','identifier','publication_date','edition_or_version','accessed_on','replaces_source_id','withdrawal_reason'] as $field): ?><dt class="col-sm-3"><?= e(ucfirst(str_replace('_',' ',$field))) ?></dt><dd class="col-sm-9 text-break"><?= nl2br(e((string)($source[$field]??'—'))) ?></dd><?php endforeach; ?><dt class="col-sm-3">URL</dt><dd class="col-sm-9 text-break"><?php if ($safeUrl): ?><a href="<?= e($source['url']) ?>" rel="noopener noreferrer" target="_blank"><?= e($source['url']) ?></a><?php else: ?><?= e($source['url']??'—') ?><?php endif; ?></dd></dl>
    <div class="d-flex flex-wrap gap-2 mb-4"><a class="btn btn-outline-secondary" href="<?= e(url('admin/treatment-sources/'.$systemId)) ?>">Source catalog</a><?php if ($canCreate): ?><a class="btn btn-outline-primary" href="<?= e(url('admin/treatment-sources/'.$systemId.'/create').'?replaces_source_id='.(int)$source['id']) ?>">Create corrected replacement</a><?php endif; ?></div>
    <?php if ($source['status']==='unverified' && $canVerify): ?><form method="post" action="<?= e(url('admin/treatment-sources/'.$systemId.'/'.$source['id'].'/verify')) ?>" class="card card-body mb-3"><?= csrfField() ?><p>Confirm that you have checked this source's bibliographic identity and provenance.</p><div><button class="btn btn-outline-primary">Mark provenance verified</button></div></form><?php endif; ?>
    <?php if ($source['status']!=='withdrawn' && $canWithdraw): ?><form method="post" action="<?= e(url('admin/treatment-sources/'.$systemId.'/'.$source['id'].'/withdraw')) ?>" class="card card-body"><?= csrfField() ?><h2 class="h5">Withdraw source</h2><p>This is terminal. It invalidates all linked protocols and withdraws affected published content. You need withdrawal authority for every affected system; references remain in history.</p><label for="withdrawal-reason" class="form-label">Reason</label><textarea class="form-control mb-3" id="withdrawal-reason" name="reason" required></textarea><div><button class="btn btn-outline-danger">Withdraw source and invalidate references</button></div></form><?php endif; ?>
</div>
